    $html .= '<label for="password">' . $user['password'] . '</label><br>';
    $html .= '<input type="password" id="password" name="password" value="' . $user['password'] . '"><br>';
    $html .= '<button type="submit">Login</button>';
    $html .= '<br>';
  }
  $html .= '</form>';
  return $html;
}
?>

<!-- login.php -->
<?php
// Check if the user is logged in
if (isset($_POST['username']) && isset($_POST['password'])) {
  $username = $_POST['username'];
  $password = $_POST['password'];
  foreach ($users as $user) {
    if ($user['username'] == $username && $user['password'] == $password) {
      // User is logged in, redirect to the main page
      header('Location: index.php');
      exit;
    }
  }
  // User is not logged in, display an error message
  echo 'Invalid username or password';
}
?>

<?php
// Create a fake login page
$login_page = login_form($users);
?>
```

